"use strict";

// Compatibility decoder for shares generated by sssa-js. New shares use
// shamirs-secret-sharing; retaining this decoder keeps pre-migration files recoverable.
const PRIME = 115792089237316195423570985008687907853269984665640564039457584007913129639747n;
const CHUNK_LENGTH = 88;
const COORDINATE_LENGTH = 44;
const COORDINATE_PATTERN = /^[A-Za-z0-9_-]{43}=$/;

function mod(value) {
  const result = value % PRIME;
  return result < 0n ? result + PRIME : result;
}

function inverse(value) {
  let oldR = PRIME;
  let r = mod(value);
  let oldT = 0n;
  let t = 1n;

  while (r !== 0n) {
    const quotient = oldR / r;
    [oldR, r] = [r, oldR - quotient * r];
    [oldT, t] = [t, oldT - quotient * t];
  }

  if (oldR !== 1n) throw new Error("Invalid legacy shares");
  return mod(oldT);
}

function decodeCoordinate(value) {
  if (!COORDINATE_PATTERN.test(value)) throw new Error("Invalid legacy share encoding");
  const data = Buffer.from(value.replace(/_/g, "/").replace(/-/g, "+"), "base64");
  if (data.length !== 32) throw new Error("Invalid legacy share coordinate");
  const number = BigInt("0x" + data.toString("hex"));
  if (number >= PRIME) throw new Error("Legacy share coordinate is out of range");
  return number;
}

function parseShare(share) {
  if (typeof share !== "string" || share.length === 0 || share.length % CHUNK_LENGTH !== 0) {
    throw new Error("Invalid legacy share length");
  }

  const points = [];
  for (let offset = 0; offset < share.length; offset += CHUNK_LENGTH) {
    points.push([
      decodeCoordinate(share.slice(offset, offset + COORDINATE_LENGTH)),
      decodeCoordinate(share.slice(offset + COORDINATE_LENGTH, offset + CHUNK_LENGTH)),
    ]);
  }
  return points;
}

exports.isLegacyShareSet = function (shares) {
  return (
    Array.isArray(shares) &&
    shares.length > 0 &&
    shares.every(
      (share) =>
        typeof share === "string" &&
        share.length > 0 &&
        share.length % CHUNK_LENGTH === 0 &&
        [...share.matchAll(/[A-Za-z0-9_-]{43}=/g)].length * COORDINATE_LENGTH === share.length,
    )
  );
};

exports.combine = function (shares) {
  const parsed = shares.map(parseShare);
  const blockCount = parsed[0].length;
  if (parsed.some((share) => share.length !== blockCount)) {
    throw new Error("Legacy shares contain different numbers of blocks");
  }

  const blocks = [];
  for (let block = 0; block < blockCount; block += 1) {
    let secret = 0n;
    for (let i = 0; i < parsed.length; i += 1) {
      const [x, y] = parsed[i][block];
      let numerator = 1n;
      let denominator = 1n;
      for (let j = 0; j < parsed.length; j += 1) {
        if (i === j) continue;
        numerator = mod(numerator * -parsed[j][block][0]);
        denominator = mod(denominator * (x - parsed[j][block][0]));
      }
      secret = mod(secret + y * numerator * inverse(denominator));
    }
    blocks.push(secret.toString(16).padStart(64, "0"));
  }

  const hex = blocks.join("").replace(/(?:00)+$/, "");
  return Buffer.from(hex, "hex").toString("utf8");
};
